using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgeProvenanceFilterTests{[Fact]public void Created_by_filter_normalizes(){var caller=new List<string>{"z","a","a"};var f=new AstronomyKnowledgeProvenanceFilter(caller);caller.Add("b");Assert.Equal(new[]{"a","z"},f.CreatedBy);Assert.Throws<NotSupportedException>(()=>((IList<string>)f.CreatedBy!).Add("c"));}[Fact]public void Null_means_absent(){Assert.Null(new AstronomyKnowledgeProvenanceFilter().CreatedBy);}[Fact]public void Rejects_empty_or_blank(){Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeProvenanceFilter([]));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeProvenanceFilter([" "]));}}
